// Workers forbid reusing a database connection across requests, so on Cloudflare
// each request gets its own client, keyed by that request's execution context.
const clientsByRequest = new WeakMap<object, PrismaClient>()

function getWorkerClient(): PrismaClient {
  const requestKey = getCloudflareContext().ctx as object
  let client = clientsByRequest.get(requestKey)
  if (!client) {
    const connectionString = process.env.DATABASE_URL
    if (!connectionString) {
      throw new Error('DATABASE_URL is not set')
    }
    const adapter = new PrismaPg({ connectionString, maxUses: 1 })
    client = new PrismaClient({ adapter })
    clientsByRequest.set(requestKey, client)
  }
  return client
}

