// Existing code imports a `prisma` singleton; this proxy keeps that API while
// resolving the right client (per-request on Workers, global on Node/Vercel).
export const prisma = new Proxy({} as PrismaClient, {
  get(_target, property) {
    const client = isCloudflareWorker ? getWorkerClient() : getNodeClient()
    const value = Reflect.get(client, property, client)
    return typeof value === 'function' ? value.bind(client) : value
  },
})
